changeSet.sql:
ALTER TABLE sources
    ADD COLUMN authority_id UUID REFERENCES authorities(id) ON DELETE SET NULL;
CREATE INDEX idx_sources_authority_id ON sources(authority_id);

ALTER TABLE node_sources
    ADD COLUMN location TEXT;

DROP TABLE node_authorities;

rollback.sql:
CREATE TABLE node_authorities (
    node_id         UUID NOT NULL REFERENCES nodes(id)       ON DELETE CASCADE,
    authority_id    UUID NOT NULL REFERENCES authorities(id) ON DELETE CASCADE,
    stance          TEXT NOT NULL
                    CHECK (stance IN ('HOLDS','OPPOSES','NEUTRAL')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (node_id, authority_id)
);
CREATE INDEX idx_node_authorities_authority_id ON node_authorities(authority_id);

ALTER TABLE node_sources DROP COLUMN location;

DROP INDEX IF EXISTS idx_sources_authority_id;
ALTER TABLE sources DROP COLUMN authority_id;
